  // 3) Update displayName to a different non-blank value
  const nextDisplayName1 = `${RandomGenerator.name()} ${RandomGenerator.alphabets(4)}`;
  const updated1 =
    await api.functional.multiUserTodo.member.profiles.updateProfile(
      memberConnection,
