  TestValidator.equals("createdAt unchanged", updated1.createdAt, createdAt);
  TestValidator.notEquals(
    "updatedAt changed",
    updated1.updatedAt,
    initialUpdatedAt,
  );
  // 4) Update again to another non-blank value
