    updated3.memberId,
    memberId,
  );
  TestValidator.equals(
    "createdAt unchanged when re-saving",
    updated3.createdAt,
    createdAt,
  );
  const updated4 =
    await api.functional.multiUserTodo.member.profiles.updateProfile(
      memberConnection,
      {
