import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_profile_snapshots_update_direct_and_restore_and_cross_member_denied(
  connection: api.IConnection,
): Promise<void> {
  // --- Member A join ---
  const memberAConnection: api.IConnection = { host: connection.host };
  const memberAAuthorized = await authorize_member_join(memberAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<boolean>(),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  // --- Member B join ---
  const memberBConnection: api.IConnection = { host: connection.host };
  const memberBAuthorized = await authorize_member_join(memberBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<boolean>(),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  // ========== Scenario 1: Direct display name update creates history snapshot ==========
  const memberADisplayName1 = RandomGenerator.name();
  const update1 =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: memberADisplayName1,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(update1);
  TestValidator.equals(
    "memberId stays same",
    update1.memberId,
    memberAAuthorized.id,
  );
  TestValidator.equals(
    "displayName matches",
    update1.displayName,
    memberADisplayName1,
  );
  TestValidator.equals("deletedAt is null", update1.deletedAt, null);
  const updatedAt1 = update1.updatedAt;
  const memberADisplayName2 = RandomGenerator.name();
  const update2 =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: memberADisplayName2,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(update2);
  TestValidator.equals(
    "memberId stays same after second update",
    update2.memberId,
    memberAAuthorized.id,
  );
  TestValidator.equals(
    "displayName updated",
    update2.displayName,
    memberADisplayName2,
  );
  TestValidator.equals("deletedAt remains null", update2.deletedAt, null);
  TestValidator.predicate(
    "updatedAt increases after second update",
    update2.updatedAt !== updatedAt1 && update2.updatedAt > updatedAt1,
  );
  // Best-effort snapshot id extraction from response payload (if API includes it).
  const snapshotIdFromUpdate1: string | undefined =
    (
      update1 as {
        snapshotId?: string;
        restoreSnapshotId?: string;
        restore_snapshot_id?: string;
      }
    ).snapshotId ??
    (
      update1 as {
        restoreSnapshotId?: string;
      }
    ).restoreSnapshotId;
  // ========== Scenario 2: Restore from an owned (restorable) snapshot updates display name ==========
  if (snapshotIdFromUpdate1 !== undefined) {
    const restoreAttempt =
      await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
        memberAConnection,
        {
          body: {
            // Value may be ignored/validation-only for restore path; server source of truth is snapshot.
            display_name: RandomGenerator.name(),
            restore_snapshot_id: snapshotIdFromUpdate1,
          } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
        },
      );
    typia.assert(restoreAttempt);
    TestValidator.equals(
      "restored memberId matches",
      restoreAttempt.memberId,
      memberAAuthorized.id,
    );
    TestValidator.equals(
      "restored deletedAt is null",
      restoreAttempt.deletedAt,
      null,
    );
    TestValidator.equals(
      "restored displayName equals snapshot prior value",
      restoreAttempt.displayName,
      memberADisplayName1,
    );
    TestValidator.predicate(
      "updatedAt changes on restore",
      restoreAttempt.updatedAt !== update2.updatedAt &&
        restoreAttempt.updatedAt > update2.updatedAt,
    );
  }
  // ========== Scenario 3: Cross-member restore attempt is denied safely ==========
  const bDisplayNameBefore = RandomGenerator.name();
  const bUpdateBefore =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberBConnection,
      {
        body: {
          display_name: bDisplayNameBefore,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(bUpdateBefore);
  TestValidator.equals(
    "B memberId matches",
    bUpdateBefore.memberId,
    memberBAuthorized.id,
  );
  const updatedAtBBefore = bUpdateBefore.updatedAt;
  const crossMemberSnapshotId: string | undefined = snapshotIdFromUpdate1;
  await TestValidator.error(
    "cross-member restore should be rejected",
    async () => {
      const restoreSnapshotId =
        crossMemberSnapshotId ?? typia.random<string & tags.Format<"uuid">>();
      await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
        memberBConnection,
        {
          body: {
            display_name: RandomGenerator.name(),
            restore_snapshot_id: restoreSnapshotId,
          } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
        },
      );
    },
  );
  // Without a dedicated GET endpoint, we validate safety by ensuring the profile can still be updated
  // to a known value and retains that member scope. We cannot reliably prove updatedAt immutability
  // after a denied request without read access.
  const bDisplayNameAfter = RandomGenerator.name();
  const bUpdateAfter =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberBConnection,
      {
        body: {
          display_name: bDisplayNameAfter,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(bUpdateAfter);
  TestValidator.equals(
    "B memberId unchanged",
    bUpdateAfter.memberId,
    memberBAuthorized.id,
  );
  TestValidator.equals(
    "B can still update after denied attempt",
    bUpdateAfter.displayName,
    bDisplayNameAfter,
  );
  // Soft-check: updatedAt should be at or after the previous known value.
  TestValidator.predicate(
    "updatedAt is not earlier than before",
    bUpdateAfter.updatedAt >= updatedAtBBefore,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoMember";
import type { IMultiUserTodoUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfile";
import type { IMultiUserTodoUserProfileSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfileSnapshot";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_profile_snapshots_update_repeated_and_restore_state_and_unauthorized(
  connection: api.IConnection,
): Promise<void> {
  // 1) Join as a member.
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized: IMultiUserTodoMember.IAuthorized =
    await authorize_member_join(memberConnection, {});
  const memberId = authorized.id;
  // Helper to call update with direct display_name.
  const updateDisplayName = async (displayName: string) => {
    const updated =
      await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
        memberConnection,
        {
          body: {
            display_name: displayName,
            restore_snapshot_id: null,
          } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
        },
      );
    typia.assert(updated);
    return updated;
  };
  // Scenario 1: Repeated direct updates.
  const name1 = RandomGenerator.name();
  const profile1 = await updateDisplayName(name1);
  TestValidator.equals("memberId matches", profile1.memberId, memberId);
  TestValidator.equals("deletedAt is null", profile1.deletedAt, null);
  const name2 = RandomGenerator.name();
  const profile2 = await updateDisplayName(name2);
  TestValidator.equals(
    "displayName updated to latest value",
    profile2.displayName,
    name2,
  );
  TestValidator.equals("memberId matches", profile2.memberId, memberId);
  TestValidator.equals("deletedAt is null", profile2.deletedAt, null);
  TestValidator.predicate(
    "updatedAt increases",
    profile2.updatedAt > profile1.updatedAt,
  );
  const name3 = RandomGenerator.name();
  const profile3 = await updateDisplayName(name3);
  TestValidator.equals(
    "displayName updated to latest value",
    profile3.displayName,
    name3,
  );
  TestValidator.equals("memberId matches", profile3.memberId, memberId);
  TestValidator.equals("deletedAt is null", profile3.deletedAt, null);
  TestValidator.predicate(
    "updatedAt increases again",
    profile3.updatedAt > profile2.updatedAt,
  );
  const name4 = RandomGenerator.name();
  const profile4 = await updateDisplayName(name4);
  TestValidator.equals(
    "displayName updated to latest value",
    profile4.displayName,
    name4,
  );
  TestValidator.equals("memberId matches", profile4.memberId, memberId);
  TestValidator.equals("deletedAt is null", profile4.deletedAt, null);
  TestValidator.predicate(
    "updatedAt increases again",
    profile4.updatedAt > profile3.updatedAt,
  );
  // Scenario 3: Unauthorized (no session) update is denied.
  const unauthorizedConnection: api.IConnection = { host: connection.host };
  const unauthorizedDisplayName = RandomGenerator.name();
  await TestValidator.httpError(
    "unauthorized update should be denied",
    [401, 403],
    async () => {
      await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
        unauthorizedConnection,
        {
          body: {
            display_name: unauthorizedDisplayName,
            restore_snapshot_id: null,
          } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
        },
      );
    },
  );
  // Validate profile is unchanged by checking displayName remains the last authorized value.
  const profileAfterUnauthorized = await updateDisplayName(name4);
  TestValidator.equals(
    "displayName unchanged after unauthorized attempt",
    profileAfterUnauthorized.displayName,
    name4,
  );
  TestValidator.equals(
    "memberId still matches",
    profileAfterUnauthorized.memberId,
    memberId,
  );
  TestValidator.equals(
    "deletedAt is null",
    profileAfterUnauthorized.deletedAt,
    null,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoMember";
import type { IMultiUserTodoUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfile";
import type { IMultiUserTodoUserProfileSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfileSnapshot";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_profile_snapshots_restore_snapshot_source_of_truth_and_cross_member_denied(
  connection: api.IConnection,
): Promise<void> {
  const memberAConnection: api.IConnection = { host: connection.host };
  const memberAAuth = await authorize_member_join(memberAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.pick([true, false]),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  const memberBConnection: api.IConnection = { host: connection.host };
  const memberBAuth = await authorize_member_join(memberBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.pick([true, false]),
    } satisfies IMultiUserTodoMember.IJoin,
  });
  // Member A: direct updates to create some snapshot history.
  const displayNameA: string & tags.MinLength<1> = typia.random<
    string & tags.MinLength<1>
  >();
  const displayNameB: string & tags.MinLength<1> = typia.random<
    string & tags.MinLength<1>
  >();
  const profileAfterA =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: displayNameA,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(profileAfterA);
  const profileAfterB =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: displayNameB,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(profileAfterB);
  TestValidator.equals(
    "memberId matches acting member (A)",
    profileAfterB.memberId,
    memberAAuth.id,
  );
  TestValidator.equals("deletedAt null (A)", profileAfterB.deletedAt, null);
  // Scenario 1 (best-effort due to missing snapshot-list/read APIs):
  // Attempt a restore while providing a different display_name.
  const restoreSnapshotId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const providedDisplayNameDifferent: string & tags.MinLength<1> = typia.random<
    string & tags.MinLength<1>
  >();
  const profileAfterRestoreAttempt =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          restore_snapshot_id: restoreSnapshotId,
          display_name: providedDisplayNameDifferent,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(profileAfterRestoreAttempt);
  TestValidator.equals(
    "memberId matches acting member (A) after restore attempt",
    profileAfterRestoreAttempt.memberId,
    memberAAuth.id,
  );
  TestValidator.equals(
    "deletedAt null (A) after restore attempt",
    profileAfterRestoreAttempt.deletedAt,
    null,
  );
  TestValidator.notEquals(
    "updatedAt changes after restore attempt",
    profileAfterB.updatedAt,
    profileAfterRestoreAttempt.updatedAt,
  );
  // Scenario 2 (history continuity via direct-update semantics):
  const directUpdateValueA: string & tags.MinLength<1> = typia.random<
    string & tags.MinLength<1>
  >();
  const directUpdateValueB: string & tags.MinLength<1> = typia.random<
    string & tags.MinLength<1>
  >();
  const profileAfterDirectA =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: directUpdateValueA,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(profileAfterDirectA);
  const profileAfterDirectB =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberAConnection,
      {
        body: {
          display_name: directUpdateValueB,
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(profileAfterDirectB);
  TestValidator.equals(
    "direct update value applied A",
    profileAfterDirectA.displayName,
    directUpdateValueA,
  );
  TestValidator.equals(
    "direct update value applied B",
    profileAfterDirectB.displayName,
    directUpdateValueB,
  );
  // Scenario 3: Cross-member restore denied (best-effort: validate denial by expecting error).
  const crossMemberRestoreId: string & tags.Format<"uuid"> = restoreSnapshotId;
  await TestValidator.error(
    "cross-member restore should be denied",
    async () => {
      await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
        memberBConnection,
        {
          body: {
            restore_snapshot_id: crossMemberRestoreId,
            display_name: typia.random<string & tags.MinLength<1>>(),
          } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
        },
      );
    },
  );
  // Post-condition: ensure member B profile remains accessible and correctly scoped.
  const memberBProfile =
    await api.functional.multiUserTodo.member.profileSnapshots.updateProfileSnapshots(
      memberBConnection,
      {
        body: {
          display_name: typia.random<string & tags.MinLength<1>>(),
          restore_snapshot_id: null,
        } satisfies IMultiUserTodoUserProfileSnapshot.IUpdate,
      },
    );
  typia.assert(memberBProfile);
  TestValidator.equals(
    "memberId matches acting member (B)",
    memberBProfile.memberId,
    memberBAuth.id,
  );
  TestValidator.equals("deletedAt null (B)", memberBProfile.deletedAt, null);
}

import api from "@ORGANIZATION/PROJECT-api";
