        typeof t.id === "string" &&
        typeof t.title === "string" &&
        typeof t.completed === "boolean" &&
        typeof t.createdAt === "string" &&
        (t.startAt === null || typeof t.startAt === "string") &&
        (t.dueAt === null || typeof t.dueAt === "string"),
    ),
  );
